mapper.select:
select count(*) as count from tb_board where bo_del_yn = 'N' and bo_type = #{boType}
and bo_title like CONCAT('%', #{searchWord}, '%')
and bo_content like CONCAT('%', #{searchWord}, '%')
and (bo_title like CONCAT('%', #{searchWord}, '%') OR bo_content like CONCAT('%', #{searchWord}, '%'))
and BO_WRITER_NAME = #{searchWord}

select A.* from ( select @ROWNUM := @ROWNUM + 1 as ROWNUM, TB.* from ( select BO_SEQ_NO as boSeqNo , BO_TYPE as boType , BO_TITLE as boTitle , BO_CONTENT as boContent , BO_WRITER as boWriter , BO_WRITER_NAME as boWriterName , BO_HIT_CNT as boHitCnt , BO_OPEN_YN as boOpenYn , BO_DEL_YN as boDelYn , REG_DATE as regDate , REG_USER as regUser , UPD_DATE as updDate , UPD_USER as updUser , (select min(file_seq_no) from tb_file_item where ref_seq_no = bo_seq_no) as fileSeqNo from tb_board where bo_del_yn = 'N' and bo_type = #{boType}
and bo_title like CONCAT('%', #{searchWord}, '%')
and bo_content like CONCAT('%', #{searchWord}, '%')
and (bo_title like CONCAT('%', #{searchWord}, '%') OR bo_content like CONCAT('%', #{searchWord}, '%'))
and BO_WRITER_NAME = #{searchWord}
order by bo_seq_no DESC ) TB, ( select @ROWNUM := 0 ) R ) A where A.ROWNUM between #{startRow} and #{endRow}

mapper.update:
update tb_board set 
	bo_hit_cnt = bo_hit_cnt + 1
where bo_seq_no = #{boSeqNo}

mapper.insert:

	select
		case count(*) when 0 then 1 else max(bo_seq_no) + 1 end as boSeqNo
	from tb_board				

insert into tb_board (
	  bo_type
	, bo_title
	, bo_content
	, bo_writer
	, bo_writer_name
	, bo_hit_cnt
	, bo_open_yn
	, bo_del_yn
	, reg_date
	, reg_user			
) values (
	  #{boType}
	, #{boTitle}
	, #{boContent}
	, #{boWriter}
	, #{boWriterName}
	, 0
	, COALESCE(#{boOpenYn}, 'N')
	, 'N'
	, now()
	, #{boWriter}
)

mapper.update:
update tb_board set 
		bo_title 		= #{boTitle}
	, 	bo_content 		= #{boContent}
	, 	bo_open_yn 		= #{boOpenYn}
	,	upd_date		= now()
	,	upd_user		= #{updUser}
where 
	bo_seq_no = #{boSeqNo}


update tb_board set
		bo_del_yn 	= 'Y'
	, 	upd_date 	= now()
	, 	upd_user	= #{updUser}
where
	bo_seq_no = #{boSeqNo}
